insert into public.jobs (slug, employer_name, employer_verified, title, job_type, campus_location, work_hours, salary_text, deadline, description, requirements, application_instructions, is_featured)
values
  ('sales-attendant-needed-umudike', 'Umudike Choice Retail Store', true, 'Sales Attendant Needed', 'Part-time', 'MOUAU, Umudike', 'Flexible student shifts (Mon–Sat)', '₦45,000 – ₦55,000 / month', '30 Nov 2026', 'A retail shop near MOUAU Main Gate is looking for a responsible and hardworking sales attendant.', array['Good communication skills', 'Ability to attend to customers politely', 'Basic numerical and record-keeping skills', 'Honesty and punctuality'], 'Apply via MOUAU Connect or visit Umudike Choice Retail Store opposite MOUAU Main Gate between 10 AM and 3 PM with a short CV.', true),
  ('frontend-react-tailwind-developer-contract', 'Abia Tech Labs', true, 'Frontend React & Tailwind Developer (Contract)', 'Remote', 'Remote', '15–20 hrs / week (Remote)', '₦120,000 / month', '15 Dec 2026', 'Build responsive web dashboards for local SMEs. Ideal for computer science or engineering students at MOUAU or ABSU.', array['React.js & Tailwind CSS proficiency', 'GitHub portfolio with 2+ projects', 'Reliable internet connection'], 'Submit your GitHub profile and portfolio link through MOUAU Connect.', true),
  ('event-photographer-reels-editor-colmas', 'COLMAS Dinner Committee', true, 'Event Photographer & Reels Editor for Department Dinner', 'Freelance', 'MOUAU, Umudike', '1 Evening (5 PM – 11 PM)', '₦45,000 flat gig pay', '25 Nov 2026', 'Cover red carpet photos and deliver two 60-second highlight reels within 48 hours.', array['DSLR/Mirrorless camera + lighting', 'CapCut or Premiere Pro editing samples'], 'Share your sample portfolio link when applying.', false),
  ('graduate-bakery-supervisor-umuahia', 'Golden Crust Bakery Umuahia', true, 'Graduate / Full-Time Bakery Supervisor & Cashier', 'Full-time', 'Umuahia & Surroundings', 'Mon–Sat (8 AM – 5 PM)', '₦85,000 / month', '10 Dec 2026', 'Supervise daily bread & pastry sales, inventory reconciliation, and POS operations.', array['OND/HND/B.Sc or awaiting NYSC', 'Strong bookkeeping and customer service'], 'Apply through MOUAU Connect with your CV and availability date.', false),
  ('agribusiness-field-intern-nrcri', 'NRCRI Umudike Partner Farm', true, 'Agribusiness & Crop Monitoring Intern', 'Internship', 'MOUAU, Umudike', 'Mon–Fri (9 AM – 3 PM)', '₦40,000 monthly stipend', '20 Dec 2026', 'Assist with field data collection, crop yield documentation, and farmer cooperative onboarding.', array['300L/400L Agriculture or Economics student', 'Spreadsheet literacy'], 'Attach your SIWES/Internship letter when applying.', false),
  ('weekend-event-usher-absu-uturu', 'Uturu Events Collective', true, 'Weekend Event Ushers & Registration Desk Assistants', 'Temporary', 'ABSU, Uturu', 'Weekends only (6 hrs/day)', '₦12,000 / event day', '18 Dec 2026', 'Welcome guests, check tickets, and coordinate seating for conferences and weddings around Uturu and Okigwe.', array['Presentable and articulate', 'Punctual and team-oriented'], 'Apply via MOUAU Connect with a brief introduction.', false)
